import{z as r,x as s,o as l,c as B,q as m,j as n,D as E,d as e,s as h,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"条件期望作为投影","description":"","frontmatter":{"title":"条件期望作为投影","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/conditional-expectation-proj.md","filePath":"quant/conditional-expectation-proj.md","lastUpdated":1791413859000}'),d={name:"quant/conditional-expectation-proj.md"};function c(b,a,p,A,F,u){const i=s("Mermaid");return l(),B("div",null,[a[2]||(a[2]=m('<h1 id="条件期望作为投影" tabindex="-1">条件期望作为投影 <a class="header-anchor" href="#条件期望作为投影" aria-label="Permalink to &quot;条件期望作为投影&quot;">​</a></h1><div class="epigraph"><p>条件期望 $\\mathbb E[X\\mid\\mathcal G]$ 是 $X$ 到 $\\mathcal G$-可测平方可积随机变量的正交投影：已知信息下对 $X$ 的最佳 $L^2$ 预测。</p><footer>—— 据 Karatzas and Shreve, Brownian Motion and Stochastic Calculus, 1991, 第 1 章；Shreve, Stochastic Calculus for Finance I, 2004, 第 2 章整理</footer></div><p>上一课<a href="/quant/geometric-brownian-motion">几何布朗运动</a>给出了路径对象 \\(S_t\\)。缺口是：定价与对冲要的不是整条路径的清单，而是「给定到 \\(t\\) 的信息，对尚未实现的支付取平均」。本课把条件期望钉成 \\(L^2\\) 投影，后课的鞅、停时、换测度都只调用这条运算，不再从初等条件密度重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>初等课里 \\(\\mathbb E[X\\mid Y=y]\\) 是把密度拿 \\(y\\) 切开再归一。连续时间里信息是 \\(\\sigma\\)-代数流 \\(\\mathcal F_t\\)，不是单个随机变量。缺口是换语言：给定 \\(\\mathcal G\\subset\\mathcal F\\)，\\(\\mathbb E[X\\mid\\mathcal G]\\) 是唯一（a.s.）的 \\(\\mathcal G\\)-可测可积随机变量，使得对一切有界 \\(\\mathcal G\\)-可测 \\(Z\\)，</p> \\[\\mathbb E[Z\\mathbb E[X\\mid\\mathcal G]]=\\mathbb E[ZX]. \\]<p>这是定义，不是「先有条件密度再积分」。没有它，下一课无法写 \\(\\mathbb E[M_t\\mid\\mathcal F_s]=M_s\\)。</p><p>路径已经会动；本课不重推 GBM，只补「给定信息之后还剩下什么随机性」。</p><p><span class="marginnote">投影可以想象成影子：把阳光垂直照向「已知信息」这张平面，\\(X\\) 落在平面上的影子就是 \\(\\mathbb E[X\\mid\\mathcal G]\\)。影子是平面上离 \\(X\\) 最近的点，所以按距离平方平均最小——这正是「最佳 \\(L^2\\) 预测」的几何内容。信息一变，平面角度就变，影子随之移动；这也解释了为什么条件期望本身仍是随机变量。</span></p><h3 id="条件期望不是用样本均值代替期望" tabindex="-1">条件期望不是用样本均值代替期望 <a class="header-anchor" href="#条件期望不是用样本均值代替期望" aria-label="Permalink to &quot;条件期望不是用样本均值代替期望&quot;">​</a></h3><p>对一条已实现路径取时间平均，是遍历问题，不是 \\(\\mathbb E[\\,\\cdot\\mid\\mathcal F_t]\\)。条件期望仍是随机变量：信息变了，预测变了。把它理解成「历史上的平均价格」，后面风险中性定价会把时间序列和测度搞混。</p><p><span class="marginnote">初学者容易把 \\(\\mathbb E[X\\mid\\mathcal F_t]\\) 读成「这条路径到目前为止的平均值」。实际上它是对未来所有可能的路径取平均，只是平均时已经用上了今天的信息做筛选：今天的信息不同，参与平均的路径集合就不同，答案也不同。时间平均是沿一条路走出来的统计量，条件期望是站在 \\(t\\) 时刻看向所有分支的预测，两者对象都不一样。</span></p><p><span class="marginnote">\\(L^2\\) 里投影的几何最干净：误差 \\(X-\\mathbb E[X\\mid\\mathcal G]\\) 与所有 \\(\\mathcal G\\)-可测方向正交。可积但非平方可积时定义仍在，只是失去正交图像。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\(L^2\\) 中，\\(\\mathbb E[\\,\\cdot\\mid\\mathcal G]\\) 是到闭子空间 \\(L^2(\\mathcal G)\\) 的正交投影，因而线性、幂等、范数不增。塔性：\\(\\mathcal H\\subset\\mathcal G\\) 则 \\(\\mathbb E[\\mathbb E[X\\mid\\mathcal G]\\mid\\mathcal H]=\\mathbb E[X\\mid\\mathcal H]\\)。已知量可提出：\\(\\mathcal G\\)-可测有界 \\(Y\\) 满足 \\(\\mathbb E[YX\\mid\\mathcal G]=Y\\mathbb E[X\\mid\\mathcal G]\\)。独立性：若 \\(X\\) 独立于 \\(\\mathcal G\\)，则 \\(\\mathbb E[X\\mid\\mathcal G]=\\mathbb E[X]\\)。Jensen：凸 \\(\\phi\\) 时 \\(\\phi(\\mathbb E[X\\mid\\mathcal G])\\le\\mathbb E[\\phi(X)\\mid\\mathcal G]\\)。</p><p>定价接口：未定权益 \\(H\\in L^2\\) 在信息 \\(\\mathcal F_t\\) 下的条件价格（尚未贴现、尚未换测度）就是投影 \\(\\mathbb E[H\\mid\\mathcal F_t]\\)。本课不引入 \\(Q\\)，只把运算准备好。</p>',16)),(l(),n(o,null,{default:E(()=>[h(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%B9%B3%E6%96%B9%E5%8F%AF%E7%A7%AF%E6%94%AF%E4%BB%98%20X%22%5D%20--%3E%20PROJ%5B%22%E5%90%91%20G%20%E5%8F%AF%E6%B5%8B%E5%AD%90%E7%A9%BA%E9%97%B4%E6%8A%95%E5%BD%B1%22%5D%0A%20%20PROJ%20--%3E%20EXG%5B%22%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20EXG%20--%3E%20TOWER%5B%22%E5%A1%94%E6%80%A7%22%5D%0A%20%20TOWER%20--%3E%20MG%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%9E%85%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"正交性解释「新息」：把 \\(X\\) 拆成已由 \\(\\mathcal G\\) 决定的部分与正交残差。布朗运动的独立增量正是残差：\\(\\mathbb E[W_t\\mid\\mathcal F_s]=W_s\\)，残差 \\(W_t-W_s\\) 与过去正交。塔性把多期预测收成一次投影，这是离散鞅证明里「取条件再取条件」的几何。Jensen 给凸支付的下界，后课期权价值对标的凸性从这里来，不必先写 PDE。",-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"塔性可以用两次过滤的骰子体会：先告诉你「点数之和是偶数」，让你猜总和；再补一句「且小于 8」。塔性说，先用粗信息算出最佳猜测、再在这个猜测基础上用细信息修正，结果与一开始就把两条信息一起用完全相同——信息可以层层收紧，但不会算出第二套答案。")],-1)),a[6]||(a[6]=t("p",null,"条件期望对 a.s. 相等敏感：两个版本只差零测集。写过程时默认取右连左极修正，那是鞅课的正则性，本课只要求可测版本存在。",-1)),(l(),n(o,null,{default:E(()=>[h(i,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%94%AF%E4%BB%98%20X%22%5D%20--%3E%20KN%5B%22%E5%B7%B2%E7%9F%A5%E9%83%A8%E5%88%86%20E%5BX%7CG%5D%EF%BC%88%E8%90%BD%E5%9C%A8%20G%20%E5%B9%B3%E9%9D%A2%EF%BC%89%22%5D%0A%20%20X%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%20X%E2%88%92E%5BX%7CG%5D%EF%BC%8C%E4%B8%8E%20G%20%E5%B9%B3%E9%9D%A2%E6%AD%A3%E4%BA%A4%22%5D%0A%20%20FT%5B%22%E7%B2%97%E4%BF%A1%E6%81%AF%20H%20%E2%8A%82%20%E7%BB%86%E4%BF%A1%E6%81%AF%20G%22%5D%20--%3E%20TW%5B%22%E5%A1%94%E6%80%A7%EF%BC%9A%E5%85%88%E5%AF%B9%20G%20%E5%86%8D%E5%AF%B9%20H%20%3D%20%E7%9B%B4%E6%8E%A5%E5%AF%B9%20H%22%5D%0A%20%20TW%20--%3E%20BR%5B%22%E5%B8%83%E6%9C%97%E4%BE%8B%EF%BC%9AE%5BW_t%7CF_s%5D%20%3D%20W_s%EF%BC%8C%E5%A2%9E%E9%87%8F%E4%B8%8E%E8%BF%87%E5%8E%BB%E6%AD%A3%E4%BA%A4%22%5D%0A%20%20BR%20--%3E%20MG%5B%22%E6%B2%BF%E6%97%B6%E9%97%B4%E6%8E%92%E6%88%90%E9%9E%85%EF%BC%88%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%89%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=m('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲正则条件分布的存在定理，不把贝叶斯更新写成滤波。也不引入 ess sup、对偶预测。后课默认：见到 \\(\\mathbb E[\\,\\cdot\\mid\\mathcal F_t]\\) 即投影；塔性、可提出、独立性三条随手用。下一课<a href="/quant/martingale-local">鞅与局部鞅</a>把投影沿时间排成过程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件期望是到已知信息子空间的 \\(L^2\\) 投影。</li><li>塔性、可提出、独立性是后课仅有的运算规则。</li><li>它是随机变量，不是一条路径上的时间平均。</li><li>布朗增量与过去正交，正是投影的例子。</li><li>出处：Karatzas–Shreve 第 1 章；Shreve SDE I 第 2 章。</li></ul>',4))])}const G=r(d,[["render",c]]);export{D as __pageData,G as default};
